mapper.select:
select
, pro.State as state, mn.* from Sec_Bidding_Project mn
left join Sec_Bidding_Plan sbp on sbp.Bp_Id = mn.Bp_Id left join Sec_Procurement_Plan spp on spp.pp_id= mn.pp_id where mn.Bp_Id = #{bpId}

mapper.sql:

    and bp.Te_Id = #{params.teId}


    and bp.State=#{params.state}


    and bp.Bp_Id=#{params.bpId}


    and bp.Bp_Name like concat('%',#{params.bpName},'%')


    and bp.Bp_Create_Uname like concat('%',#{params.bpCreateUname},'%')

and bp.Bp_Id in
(select mn.Bp_Id
from Sec_Bidding_Project mn
left join Pre_Project pro on mn.P_Id=pro.P_Id
${params.authSql}

    and pro.P_Name like concat('%',#{params.pName},'%')

)

mapper.select:
select (select sum(Sec_Money) from Sec_Info_Change where Bpc_Id=bp.Bpc_Id) as secMoneys, (select count(1) from Sec_Info_Change where Bpc_Id=bp.Bpc_Id) as secInfoTotal, c1.C_Name as bpTendereeName, bp.*, u2.U_Name as responsibleLeaderName from Sec_Bidding_Plan_Change bp left join SYS_Company c1 on c1.C_Id=bp.Bp_Tenderee left join SYS_User u2 on u2.U_Id=bp.Responsible_Leader where 1=1
order by bp.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by bp.Bp_Create_Time DESC
limit #{params.start},#{params.size}
